func (req *ReplaceAccountRoleRequest) Bind(_ *http.Request) error {
	if req.RoleID == nil || req.RoleID.Int64() <= 0 {
		return errors.New("role_id is required")
	}
	return nil
}

func (rs *PasskeyResource) PasskeyEnrollmentChallenge(w http.ResponseWriter, r *http.Request) {
	if !rs.requirePasskey(w, r) {
		return
	}
	claims := sessiontoken.ClaimsFromCtx(r.Context())
	result, err := rs.passkeyService.StartOperatorPasskeyEnrollment(r.Context(), int64(claims.ID), common.ParseClientIP(r))
	if err != nil {
		mapOperatorPasskeyError(w, r, err)
		return
	}
	render.JSON(w, r, result)
}

func (rs *PasskeyResource) PasskeyList(w http.ResponseWriter, r *http.Request) {
	if !rs.requirePasskey(w, r) {
		return
	}
	claims := sessiontoken.ClaimsFromCtx(r.Context())
	credentials, err := rs.passkeyService.ListOperatorPasskeyCredentials(r.Context(), int64(claims.ID))
	if err != nil {
		mapOperatorPasskeyError(w, r, err)
		return
	}
	render.JSON(w, r, credentials)
}

func (rs *Resource) ListAccountTenantAccess(w http.ResponseWriter, r *http.Request) {
	accountID, ok := common.ParseInt64IDWithError(w, r, "accountId", "invalid account ID")
	if !ok {
		return
	}
	entries, err := rs.identity.ListAccountTenantAccess(r.Context(), accountID)
	rs.respondAccess(w, r, entries, err, http.StatusOK, "Account school access retrieved successfully")
}

func (rs *Resource) RevokeAccountTenantAccess(w http.ResponseWriter, r *http.Request) {
	accountID, schoolID, ok := parseAccountTenantParams(w, r)
	if !ok {
		return
	}
	entries, err := rs.identity.RevokeAccountTenantAccess(r.Context(), accountID, schoolID, operatorIDFromContext(r), clientIP(r))
	rs.respondAccess(w, r, entries, err, http.StatusOK, "School access revoked successfully")
}

