func (f *AccountMFAFlows) GetGlobalMFAOverride(ctx context.Context, accountID int64) (string, error) {
	override, found, err := f.records.FindGlobalOverride(ctx, accountID)
	if err != nil {
		return "", fmt.Errorf("load global mfa override: %w", err)
	}
	if !found {
		return domain.MFAAdminOverrideNone, nil
	}
	return override.Override, nil
}

func (f *AccountMFAFlows) GetTenantMFAOverride(ctx context.Context, accountID, tenantID int64) (string, error) {
	if tenantID == 0 {
		return domain.MFAAdminOverrideNone, nil
	}
	override, found, err := f.records.FindTenantOverride(ctx, accountID, tenantID)
	if err != nil {
		return "", fmt.Errorf("load tenant mfa override: %w", err)
	}
	if !found {
		return domain.MFAAdminOverrideNone, nil
	}
	return override.Override, nil
}

func (f *AccountMFAFlows) ResendChallenge(ctx context.Context, challengeToken string, ip net.IP) (string, error) {
	claims, err := f.codec.ParseChallengeToken(challengeToken)
	if err != nil {
		return "", identityaccess.ErrMFAChallengeTokenInvalid
	}
	return f.resend(ctx, claims, ip)
}

func (f *AccountMFAFlows) ResendChallengeForScope(ctx context.Context, challengeToken string, ip net.IP, expectedScope string) (string, error) {
	claims, err := f.codec.ParseChallengeToken(challengeToken)
	if err != nil {
		return "", identityaccess.ErrMFAChallengeTokenInvalid
	}
	if claims.Scope != expectedScope {
		return "", identityaccess.ErrMFAUnsupportedScope
	}
	return f.resend(ctx, claims, ip)
}

func (p *AccountPasskey) ListActiveCredentials(ctx context.Context, accountID int64) (result []domain.AccountPasskeyCredential, err error) {
	err = p.run(ctx, "list_active_account_passkeys", func(txCtx context.Context, stats *domain.OperationStats) error {
		credentials, queryStats, listErr := p.store.ListActiveAccountPasskeys(txCtx, accountID)
		stats.Add(queryStats)
		if listErr != nil {
			return listErr
		}
		result = credentials
		return nil
	})
	return result, err
}

func (p *AccountPasskey) RecordUse(ctx context.Context, id int64, credentialJSON json.RawMessage, usedAt time.Time) error {
	return p.run(ctx, "record_account_passkey_use", func(txCtx context.Context, stats *domain.OperationStats) error {
		if !json.Valid(credentialJSON) {
			return domain.ErrPasskeyJSONInvalid
		}
		changed, queryStats, err := p.store.UpdateAccountPasskeyAfterUse(txCtx, id, credentialJSON, usedAt)
		stats.Add(queryStats)
		return stateChange(changed, err, identityaccess.ErrAccountPasskeyNotFound)
	})
}

func (p *AccountPasskey) RevokeCredential(ctx context.Context, accountID, id int64, revokedAt time.Time) error {
	return p.run(ctx, "revoke_account_passkey", func(txCtx context.Context, stats *domain.OperationStats) error {
		changed, queryStats, err := p.store.RevokeAccountPasskey(txCtx, accountID, id, revokedAt)
		stats.Add(queryStats)
		return stateChange(changed, err, identityaccess.ErrAccountPasskeyNotFound)
	})
}

func (f *AccountPasskeyFlows) ListCredentials(ctx context.Context, accountID int64) ([]domain.PasskeyCredentialSummary, error) {
	rows, err := f.records.ListActiveCredentials(ctx, accountID)
	if err != nil {
		return nil, err
	}
	summaries := make([]domain.PasskeyCredentialSummary, 0, len(rows))
	for _, row := range rows {
		summaries = append(summaries, domain.SummarizeAccountPasskey(row))
	}
	return summaries, nil
}

func (f *AccountPasskeyFlows) RevokeCredential(ctx context.Context, accountID, credentialID int64) error {
	if err := f.records.RevokeCredential(ctx, accountID, credentialID, f.now()); err != nil {
		if errors.Is(err, identityaccess.ErrAccountPasskeyNotFound) {
			return identityaccess.ErrPasskeyNotFound
		}
		return err
	}
	return nil
}

