func (c *OperatorMFAChallenge) Validate() error {
	switch {
	case c.OperatorID <= 0:
		return errors.New("operator_id is required")
	case c.CodeHash == "":
		return errors.New("code_hash is required")
	case c.ExpiresAt.IsZero():
		return errors.New("expires_at is required")
	}
	return nil
}

func (d *OperatorTrustedDevice) Validate() error {
	switch {
	case d.OperatorID <= 0:
		return errors.New("operator_id is required")
	case d.TokenHash == "":
		return errors.New("token_hash is required")
	case d.ExpiresAt.IsZero():
		return errors.New("expires_at is required")
	}
	return nil
}

func (t *PasswordResetToken) Validate(now time.Time) error {
	switch {
	case t.AccountID <= 0:
		return errors.New("account ID is required")
	case t.Token == "":
		return errors.New("token value is required")
	case !t.Expiry.After(now):
		return errors.New("token has already expired")
	case t.Used:
		return errors.New("token has already been used")
	}
	return nil
}

func (w PasswordResetWindow) Exceeded(allowed int, now time.Time) bool {
	return w.Attempts > allowed && w.RetryAt.After(now)
}

func (i SchoolInvitation) Redeemable(now time.Time) bool {
	return i.UsedAt == nil && i.ExpiresAt.After(now)
}

func (a *TokenAuth) CreateJWT(c AppClaims) (string, error) {
	c.IssuedAt = time.Now().Unix()
	c.ExpiresAt = time.Now().Add(a.JwtExpiry).Unix()
	claims, err := ParseStructToMap(c)
	if err != nil {
		return "", err
	}
	_, tokenString, err := a.JwtAuth.Encode(claims)
	return tokenString, err
}

func (a *TokenAuth) CreateRefreshJWT(c RefreshClaims) (string, error) {
	c.IssuedAt = time.Now().Unix()
	if c.ExpiresAt <= 0 {
		c.ExpiresAt = time.Now().Add(a.JwtRefreshExpiry).Unix()
	}
	claims, err := ParseStructToMap(c)
	if err != nil {
		return "", err
	}
	_, tokenString, err := a.JwtAuth.Encode(claims)
	return tokenString, err
}
